param([string]$ReleaseNotesPath = "", [string]$KeyPath = "", [switch]$Publish)
$ErrorActionPreference = "Stop"
$repo = Split-Path -Parent $PSScriptRoot
$app = Join-Path $repo 'youle_desktop'
$gitRoot = (& git -C $repo rev-parse --show-toplevel).Trim()
if ($LASTEXITCODE -ne 0 -or (Resolve-Path -LiteralPath $gitRoot).Path -ne (Resolve-Path -LiteralPath $repo).Path) { throw 'Wrong Git root' }
# Prepare/review the version bump and commit before entering this release batch.
# The tracked native host is regenerated by build:chrome-host below. Its local
# build output is not a source change and must not force a binary-only commit.
& git -C $repo diff --quiet HEAD -- . ':(exclude)youle_desktop/resources/bin/haolo-chrome-native-host.exe'
if ($LASTEXITCODE -ne 0) { throw 'Release source has uncommitted tracked changes. Review and commit the release candidate first.' }
if ($Publish -and !$ReleaseNotesPath) { throw 'A JSON release-notes file with zh-CN, zh-Hant and en is required.' }
function Invoke-ReleaseStep([string]$Program, [string[]]$Arguments) {
  & $Program @Arguments
  if ($LASTEXITCODE -ne 0) { throw "$Program release step failed (exit $LASTEXITCODE)" }
}
Push-Location $repo
try {
  $version = (Get-Content -Raw -LiteralPath (Join-Path $app 'package.json') | ConvertFrom-Json).version
  Invoke-ReleaseStep 'node' @('youle_desktop/scripts/typecheck.mjs')
  Invoke-ReleaseStep 'pnpm' @('--dir', 'youle_desktop', 'run', 'build:chrome-host')
  Invoke-ReleaseStep 'pnpm' @('--dir', 'youle_desktop', 'run', 'build')
  Invoke-ReleaseStep 'pnpm' @('--dir', 'youle_desktop', 'exec', 'electron-builder', '--win', '--x64', '--dir', '--publish', 'never')
  Invoke-ReleaseStep 'pnpm' @('--dir', 'youle_desktop', 'exec', 'electron-builder', '--win', 'nsis', '--x64', '--prepackaged', 'release/win-unpacked', '--publish', 'never')
  Invoke-ReleaseStep 'node' @('youle_desktop/scripts/verify-windows-release.cjs')
  $installer = Join-Path $app "release/haolo_desktop-$version-Setup.exe"
  if (!(Test-Path -LiteralPath ($installer + '.support-build.json'))) { throw 'Installer is missing its support build receipt' }
  if ($Publish) {
    & (Join-Path $PSScriptRoot 'upload-windows-release.ps1') -Version $version -InstallerPath $installer `
      -ReleaseNotesPath $ReleaseNotesPath -KeyPath $KeyPath -Publish `
      -ResultPath (Join-Path $app "release/app-update-release-$version.json")
  }
  Write-Host "Installer: $installer"
  Write-Host "Knowledge bundle: $installer.support-bundle.json"
  Write-Host "Published: $Publish"
} finally { Pop-Location }
